result:
.video_page{
  height: 100%;
  .video_box{
    height: calc(100% - 47px);
    overflow: auto
  }
}
.video_list{
  display: flex;
  flex-wrap: wrap;
  padding: 0 10px;
  ::v-deep .el-button--mini.is-round{
    padding: 7px 15px!important;
    font-size: 12px;
    height: inherit;
  }
  .video_item{
    width: 50%;
    margin-bottom: 35px;
    display: flex;
    height: 140px;
    .item_left{
      width: 230px;;
      height: 140px;
      background: #ebe7e7;
      border-radius: 5px;
      position: relative;
      text-align: center;
      border: 1px solid #ebe7e7;
      img{
        width: 100%;
        height: 100%;
        border-radius: 5px;
      }
      .item_tag{
        position: absolute;
        top: 10px;
        left: 10px;
        font-size: 11px;
        color: #1061ff;
        background: #cce4ff;
        display: inline-block;
        padding: 1px 5px;
        border-radius: 2px;
        margin-right: 10px;
        white-space: nowrap;
      }
    }
    .item_right{
      width: calc(100% - 200px);
      padding-left: 15px;
      display: flex;
      flex-direction: column;
      justify-content: space-between;
      .item_title{
        color: #000;
        font-family: '黑体';
        white-space: nowrap;
        overflow: hidden;
        text-overflow: ellipsis;
        font-weight: bold;
        font-size: 16px;
      }
      .right_footer{
        font-size: 14px;
      }
    }
  }
}

::-webkit-scrollbar{
  width: 5px;
  height: 5px;
}
::v-deep ::-webkit-scrollbar-button{
  display: none
}
::-webkit-scrollbar-thumb{
  background: #bed4ff;
  border-radius: 3px
}
::-webkit-scrollbar-track{
  margin: 5px
}
